import {clamp} from './world.js';
export class Cockpit{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.rain=Array.from({length:80},()=>({x:Math.random(),y:Math.random(),l:.02+Math.random()*.04,s:.4+Math.random()*.8}));this.resize()}
 resize(){const d=Math.min(devicePixelRatio||1,1.5);this.canvas.width=Math.round(innerWidth*d);this.canvas.height=Math.round(innerHeight*d);this.w=innerWidth;this.h=innerHeight;this.d=d}
 draw(race,track,dt,menu=false){let c=this.ctx,w=this.w,h=this.h,d=this.d;c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,w,h);if(!race)return;const scale=w/1400,base=h*.81;let steer=race.steer;const polygon=(pts,fill)=>{c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=fill;c.fill()};
 // Rain on the windscreen and a moving wiper, deliberately before the dashboard.
 if(track.weather==='rain'){c.strokeStyle='#bfd9ed55';c.lineWidth=1;for(let r of this.rain){r.y+=dt*r.s*.7;if(r.y>1){r.y=-.1;r.x=Math.random()}c.beginPath();c.moveTo(r.x*w,r.y*h);c.lineTo((r.x-.013)*w,(r.y+r.l)*h);c.stroke()}let sweep=Math.sin(performance.now()/430)*.75;c.save();c.translate(w*.54,h*.79);c.rotate(sweep-.5);c.strokeStyle='#0c151c';c.lineWidth=5;c.beginPath();c.moveTo(0,0);c.lineTo(-w*.08,-h*.30);c.lineTo(w*.13,-h*.43);c.stroke();c.restore()}
 // A-pillars and roof trim.
 let roof=c.createLinearGradient(0,0,0,h*.13);roof.addColorStop(0,'#050b12');roof.addColorStop(1,'#0b152200');c.fillStyle=roof;c.fillRect(0,0,w,h*.12);
 polygon([[0,0],[w*.025,0],[w*.14,h*.69],[w*.075,h],[0,h]],'#08111a');polygon([[w,0],[w*.98,0],[w*.86,h*.69],[w*.925,h],[w,h]],'#08111a');c.strokeStyle='#354450';c.lineWidth=2;c.beginPath();c.moveTo(w*.025,0);c.lineTo(w*.14,h*.69);c.moveTo(w*.98,0);c.lineTo(w*.86,h*.69);c.stroke();
 // Hood at the base of the windscreen and sculpted dashboard.
 polygon([[w*.16,h*.77],[w*.3,h*.66],[w*.72,h*.66],[w*.87,h*.77]],track.weather==='rain'?'#24313b':'#40505a');c.strokeStyle='#afc0c544';c.lineWidth=1;c.beginPath();c.moveTo(w*.3,h*.665);c.lineTo(w*.72,h*.665);c.stroke();
 let dash=c.createLinearGradient(0,h*.72,0,h);dash.addColorStop(0,'#1c2b36');dash.addColorStop(.25,'#101a25');dash.addColorStop(1,'#03080f');polygon([[0,h*.78],[w*.19,h*.73],[w*.75,h*.73],[w,h*.80],[w,h],[0,h]],dash);c.strokeStyle='#51616e66';c.lineWidth=2;c.beginPath();c.moveTo(0,h*.78);c.quadraticCurveTo(w*.44,h*.68,w,h*.8);c.stroke();
 // Passenger-side vent, trim and illuminated badge.
 c.fillStyle='#050c13';c.fillRect(w*.77,h*.8,w*.13,h*.05);c.strokeStyle='#263b48';c.lineWidth=2;for(let i=1;i<5;i++){let y=h*(.8+i*.009);c.beginPath();c.moveTo(w*.775,y);c.lineTo(w*.895,y);c.stroke()}c.fillStyle='#b6c9d17a';c.font=`italic ${Math.max(8,12*scale)}px Arial`;c.fillText('TOUGE / 01',w*.76,h*.9);
 // Instrument cluster.
 const sx=w*.43,sy=h*.85,rad=Math.min(w*.085,h*.13);c.fillStyle='#040a11';c.beginPath();c.ellipse(sx,sy,rad*2.25,rad*1.1,0,0,Math.PI*2);c.fill();c.strokeStyle='#253b47';c.lineWidth=2;c.stroke();let speed=Math.round(race.speed*3.6);c.textAlign='center';c.fillStyle='#e7f9f5';c.font=`italic bold ${Math.max(24,47*scale)}px Arial`;c.fillText(String(speed).padStart(3,'0'),sx,sy+rad*.16);c.fillStyle='#7ba39f';c.font=`${Math.max(7,10*scale)}px monospace`;c.fillText('km/h',sx,sy+rad*.46);c.fillStyle='#91f6cc';c.font=`bold ${Math.max(19,29*scale)}px monospace`;c.fillText(race.gear,sx+rad*1.5,sy+rad*.12);c.font=`${Math.max(6,8*scale)}px monospace`;c.fillStyle='#7f9f9e';c.fillText('GEAR',sx+rad*1.5,sy+rad*.46);
 let ax=sx-rad*1.36;for(let i=0;i<22;i++){let a=Math.PI*.8+i/21*Math.PI*1.4;let active=i/22<race.rpm/8000;c.strokeStyle=active?(i>17?'#ff795a':'#91f6cc'):'#20333f';c.lineWidth=3;c.beginPath();c.moveTo(ax+Math.cos(a)*rad*.72,sy+Math.sin(a)*rad*.72);c.lineTo(ax+Math.cos(a)*rad*.89,sy+Math.sin(a)*rad*.89);c.stroke()}c.fillStyle='#7fa19e';c.font=`${Math.max(6,8*scale)}px monospace`;c.fillText('RPM',ax,sy+rad*.18);
 // Steering wheel with rotating spokes; remains below the road sightline.
 const wx=w*.28,wy=h*.99,wr=Math.min(w*.135,h*.23);c.save();c.translate(wx,wy);c.rotate(steer*.72);c.strokeStyle='#03070c';c.lineWidth=wr*.19;c.beginPath();c.arc(0,0,wr,0,Math.PI*2);c.stroke();c.strokeStyle='#30434d';c.lineWidth=wr*.023;c.beginPath();c.arc(0,0,wr*.91,Math.PI,Math.PI*2);c.stroke();for(let a of[0,Math.PI,Math.PI/2]){c.save();c.rotate(a);polygon([[wr*.25,-wr*.15],[wr*.9,-wr*.08],[wr*.9,wr*.07],[wr*.22,wr*.24]],'#172630');c.restore()}c.fillStyle='#0b151f';c.beginPath();c.ellipse(0,0,wr*.39,wr*.31,0,0,Math.PI*2);c.fill();c.strokeStyle='#506371';c.lineWidth=1;c.stroke();c.fillStyle='#b5d5d3';c.font=`italic bold ${Math.max(7,12*scale)}px Arial`;c.fillText('TOUGE',0,wr*.025);c.fillStyle='#91f6cc';c.fillRect(-wr*.025,-wr*1.07,wr*.05,wr*.15);c.restore();
 // Mirror frame; the WebGL rear camera is drawn behind this opening.
 if(w/h>1.2){let mw=w*.19,mh=h*.085,mx=(w-mw)/2,my=h*.125;c.strokeStyle='#04090f';c.lineWidth=8;c.strokeRect(mx,my,mw,mh);c.strokeStyle='#506775';c.lineWidth=1;c.strokeRect(mx-4,my-4,mw+8,mh+8);c.fillStyle='#728d9870';c.font='7px monospace';c.fillText('REAR VIEW',w*.5,my+mh-5)}c.textAlign='left';if(race.flash>0){c.fillStyle=`rgba(255,90,55,${race.flash*.11})`;c.fillRect(0,0,w,h)}
 }
}
